def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row if v not in (0, 8)}

    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        pattern = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
        ph, pw = len(pattern), len(pattern[0])

        # Fill the contiguous non-background rectangle containing the motif.
        seen = set()
        for sr in range(h):
            for sc in range(w):
                if grid[sr][sc] == 8 or (sr, sc) in seen:
                    continue
                stack = [(sr, sc)]
                seen.add((sr, sc))
                comp = []
                while stack:
                    y, x = stack.pop()
                    comp.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 8 and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            stack.append((ny, nx))
                if (r0, c0) in comp:
                    for y, x in comp:
                        out[y][x] = pattern[(y-r0) % ph][(x-c0) % pw]
                    break

    return out
